import sys

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0]); m = int(data[1])
    adj = [0] * n
    idx = 2
    for _ in range(m):
        u = int(data[idx]) - 1
        v = int(data[idx + 1]) - 1
        idx += 2
        adj[u] |= 1 << v
        adj[v] |= 1 << u

    rows = adj[:]
    pivot_row_of_col = {}
    r = 0
    for col in range(n):
        piv = -1
        for i in range(r, n):
            if (rows[i] >> col) & 1:
                piv = i
                break
        if piv < 0:
            continue
        rows[r], rows[piv] = rows[piv], rows[r]
        for i in range(n):
            if i != r and ((rows[i] >> col) & 1):
                rows[i] ^= rows[r]
        pivot_row_of_col[col] = r
        r += 1

    # Kernel basis: one vector per free column
    basis = []
    for c in range(n):
        if c in pivot_row_of_col:
            continue
        x = 1 << c
        for p in pivot_row_of_col:
            if (rows[pivot_row_of_col[p]] >> c) & 1:
                x |= 1 << p
        basis.append(x)

    covered = 0
    for b in basis:
        covered |= b
    if covered != (1 << n) - 1:
        print("No")
        return

    X = [0] * n
    for j, b in enumerate(basis):
        for v in range(n):
            if (b >> v) & 1:
                X[v] |= 1 << j
    print("Yes")
    print(' '.join(map(str, X)))

