import sys

def main():
    MOD = 998244353
    data = sys.stdin.buffer.read().split()
    N = int(data[0]); M = int(data[1])
    primes = [2, 3, 5, 7, 11, 13]

    # S = sum_{a=1}^{M} prod_p (1 + v_p(a) * y_p)  in R = F[y]/(y_p^2), basis = subsets (6-bit masks)
    S = [0] * 64
    for a in range(1, M + 1):
        t = a
        e = []
        for p in primes:
            c = 0
            while t % p == 0:
                t //= p
                c += 1
            e.append(c)
        for b in range(64):
            coef = 1
            for i in range(6):
                if (b >> i) & 1:
                    coef *= e[i]
            S[b] = (S[b] + coef) % MOD

    PAIRS = [(b1, b2, b1 | b2) for b1 in range(64) for b2 in range(64) if not (b1 & b2)]

    def mul(c, d):
        r = [0] * 64
        for b1, b2, b in PAIRS:
            x = c[b1] * d[b2]
            if x:
                r[b] = (r[b] + x) % MOD
        return r

    P = [0] * 64  # S^m (identity initially)
    P[0] = 1
    C = [0] * 64  # H(m) = sum_{k<m} S^k
    for ch in bin(N)[2:]:
        oneP = P[:]
        oneP[0] = (oneP[0] + 1) % MOD
        C = mul(C, oneP)          # H(2m) = H(m)*(1+S^m)
        P = mul(P, P)             # S^{2m}
        if ch == '1':
            C = [(C[i] + P[i]) % MOD for i in range(64)]  # H(2m+1)
            P = mul(P, S)                                  # S^{2m+1}

    G = mul(C, S)  # sum_{k=1}^{N} S^k
    print(sum(G) % MOD)

