class Solution:
    def maxPathLength(self, coordinates: List[List[int]], k: int) -> int:
        from bisect import bisect_left

        x0, y0 = coordinates[k]

        def lis_len(points):
            # Longest chain with strictly increasing x and y.
            # Sort by (x asc, y desc) so equal-x points can't both be picked,
            # then take strictly increasing LIS on y.
            pts = sorted(points, key=lambda p: (p[0], -p[1]))
            tails = []
            for _, y in pts:
                idx = bisect_left(tails, y)
                if idx == len(tails):
                    tails.append(y)
                else:
                    tails[idx] = y
            return len(tails)

        # Points usable strictly before k in a path, and strictly after k.
        left = [(p[0], p[1]) for p in coordinates if p[0] < x0 and p[1] < y0]
        right = [(p[0], p[1]) for p in coordinates if p[0] > x0 and p[1] > y0]

        # (best chain ending at k, counting k) + (best chain starting at k, counting k) - 1
        return lis_len(left) + lis_len(right) + 1

class Solution:
    def validSubstringCount(self, word1: str, word2: str) -> int:
        need = [0] * 26
        for ch in word2:
            need[ord(ch) - 97] += 1
        missing = len(word2)
        ans = 0
        left = 0
        for right, ch in enumerate(word1):
            i = ord(ch) - 97
            need[i] -= 1
            if need[i] >= 0:
                missing -= 1
            while missing == 0:
                j = ord(word1[left]) - 97
                need[j] += 1
                if need[j] > 0:
                    missing += 1
                left += 1
            ans += left
        return ans

class Solution:
    def kthCharacter(self, k: int) -> str:
        word = "a"
        while len(word) < k:
            word += ''.join(
                chr((ord(c) - ord('a') + 1) % 26 + ord('a')) for c in word
            )
        return word[k - 1]

from math import isqrt
from typing import List

class Solution:
    def minNumberOfSeconds(self, mountainHeight: int, workerTimes: List[int]) -> int:
        H = mountainHeight

        def capacity(T: int) -> int:
            # Total units all workers can remove if each works at most T seconds.
            total = 0
            for t in workerTimes:
                q = (2 * T) // t  # need x*(x+1) <= q
                if q <= 0:
                    continue
                x = isqrt(q)
                if x * (x + 1) > q:
                    x -= 1  # single decrement suffices: (x-1)*x <= x^2 <= q
                total += x
                if total >= H:
                    return total
            return total

        lo, hi = 1, max(workerTimes) * H * (H + 1) // 2
        while lo < hi:
            mid = (lo + hi) // 2
            if capacity(mid) >= H:
                hi = mid
            else:
                lo = mid + 1
        return lo

