class Solution:
    def gcdValues(self, nums: List[int], queries: List[int]) -> List[int]:
        from bisect import bisect_right
        maxV = max(nums)
        freq = [0] * (maxV + 1)
        for x in nums:
            freq[x] += 1

        exact = [0] * (maxV + 1)
        for g in range(maxV, 0, -1):
            c = sum(freq[g::g])
            val = c * (c - 1) // 2
            if val:
                val -= sum(exact[2 * g::g])
            exact[g] = val

        pre = [0] * (maxV + 1)
        s = 0
        for g in range(1, maxV + 1):
            if exact[g]:
                s += exact[g]
            pre[g] = s

        return [bisect_right(pre, q) for q in queries]

class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = set('aeiou')

        def at_least(m: int) -> int:
            # counts substrings containing all 5 vowels and >= m consonants
            cnt = {v: 0 for v in vowels}
            cons = 0
            left = 0
            total = 0
            for right, ch in enumerate(word):
                if ch in cnt:
                    cnt[ch] += 1
                else:
                    cons += 1
                # shrink while current window still satisfies the condition;
                # each left position passed through was a valid start for this right
                while left <= right and cons >= m and all(cnt[v] > 0 for v in vowels):
                    c = word[left]
                    if c in cnt:
                        cnt[c] -= 1
                    else:
                        cons -= 1
                    left += 1
                total += left
            return total

        return at_least(k) - at_least(k + 1)

