def count(N):
    if N < 10:
        return 0
    digits = list(map(int, str(N)))
    n = len(digits)
    d0 = digits[0]
    total = 0
    # shorter lengths
    for length in range(2, n):
        total += sum(t ** (length - 1) for t in range(1, 10))
    # same length, digit walk
    ok = True
    for i in range(n):
        if not ok:
            break
        if i == 0:
            for c in range(1, d0):
                total += c ** (n - 1)
        else:
            hi = min(digits[i] - 1, d0 - 1)
            if hi >= 0:
                total += (hi + 1) * (d0 ** (n - 1 - i))
            if digits[i] >= d0:
                ok = False
    if ok:
        total += 1
    return total

