class Solution:
    def maxValue(self, nums: List[int], k: int) -> int:
        n = len(nums)
        J = min(k, 7)
        INF = float('inf')
        sup = [[a for a in range(128) if a & x == x] for x in range(128)]

        first_time = [INF] * 128
        dp = [set() for _ in range(J + 1)]
        dp[0].add(0)
        cnt = [0] * 128
        for i in range(n):
            x = nums[i]
            for j in range(min(J, i + 1), 0, -1):
                dp[j] |= {v | x for v in dp[j - 1]}
            for a in sup[x]:
                cnt[a] += 1
            for a in range(128):
                if first_time[a] == INF and cnt[a] >= k and any(a in dp[j] for j in range(1, J + 1)):
                    first_time[a] = i

        last_time = [-1] * 128
        dp = [set() for _ in range(J + 1)]
        dp[0].add(0)
        cnt = [0] * 128
        for i in range(n - 1, -1, -1):
            x = nums[i]
            for j in range(min(J, n - i), 0, -1):
                dp[j] |= {v | x for v in dp[j - 1]}
            for a in sup[x]:
                cnt[a] += 1
            for a in range(128):
                if last_time[a] == -1 and cnt[a] >= k and any(a in dp[j] for j in range(1, J + 1)):
                    last_time[a] = i

        ans = 0
        for a in range(128):
            ta = first_time[a]
            if ta == INF:
                continue
            for b in range(128):
                if last_time[b] > ta and (a ^ b) > ans:
                    ans = a ^ b
        return ans

from typing import List

class Solution:
    def maximumValueSum(self, board: List[List[int]]) -> int:
        m, n = len(board), len(board[0])

        def insert(T, v, c):
            # T keeps top-3 (value, col) with distinct cols (per-column max), sorted desc
            for i, (tv, tc) in enumerate(T):
                if tc == c:
                    if v > tv:
                        T[i] = (v, c)
                        T.sort(key=lambda t: t[0], reverse=True)
                    return
            if len(T) < 3:
                T.append((v, c))
                T.sort(key=lambda t: t[0], reverse=True)
            elif v > T[-1][0]:
                T[-1] = (v, c)
                T.sort(key=lambda t: t[0], reverse=True)

        pre = [None] * m
        suf = [None] * m

        T = []
        for i in range(m):
            pre[i] = T[:]
            for j, v in enumerate(board[i]):
                insert(T, v, j)

        T = []
        for i in range(m - 1, -1, -1):
            suf[i] = T[:]
            for j, v in enumerate(board[i]):
                insert(T, v, j)

        ans = None
        for i in range(1, m - 1):
            Pa, Qa, row = pre[i], suf[i], board[i]
            for j in range(n):
                P = [(v, c) for v, c in Pa if c != j][:2]
                Q = [(v, c) for v, c in Qa if c != j][:2]
                if not P or not Q:
                    continue
                base = row[j]
                for pv, pc in P:
                    for qv, qc in Q:
                        if pc != qc:
                            s = base + pv + qv
                            if ans is None or s > ans:
                                ans = s
        return ans

class Solution:
    def minStartingIndex(self, s: str, pattern: str) -> int:
        n, m = len(s), len(pattern)

        def z_func(t: str):
            L = len(t)
            z = [0] * L
            l = r = 0
            for i in range(1, L):
                if i < r:
                    z[i] = min(r - i, z[i - l])
                while i + z[i] < L and t[z[i]] == t[i + z[i]]:
                    z[i] += 1
                if i + z[i] > r:
                    l, r = i, i + z[i]
            return z

        # A[i] = length of longest common prefix of s[i:] and pattern
        z1 = z_func(pattern + '#' + s)
        A = z1[m + 1:]  # A[i] for i in 0..n-1, capped at m by the '#'

        # B[e] = length of longest common suffix of s[:e] and pattern (e in 1..n)
        z2 = z_func(pattern[::-1] + '#' + s[::-1])
        B = [0] * (n + 1)
        for e in range(1, n + 1):
            B[e] = z2[m + 1 + n - e]

        # Substring starting at i matches with <= 1 mismatch
        # iff A[i] + B[i+m] >= m - 1
        for i in range(n - m + 1):
            if A[i] + B[i + m] >= m - 1:
                return i
        return -1

class Solution:
    def countGoodIntegers(self, n: int, k: int) -> int:
        from math import factorial
        fact = [factorial(i) for i in range(n + 1)]

        # Enumerate all n-digit palindromes by their first half (no leading zero),
        # keep digit multiset signature of those divisible by k.
        good = set()
        half_len = (n + 1) // 2
        for half in range(10 ** (half_len - 1), 10 ** half_len):
            s = str(half)
            pal = s + s[::-1] if n % 2 == 0 else s + s[:-1][::-1]
            if int(pal) % k == 0:
                good.add(''.join(sorted(pal)))

        # For each good multiset, count distinct n-digit arrangements (no leading zero):
        # n!/prod(cnt!) - (n-1)!*cnt0/prod(cnt!) = (n-1)!*(n - cnt0)/prod(cnt!)
        total = 0
        for sig in good:
            cnt = [0] * 10
            for ch in sig:
                cnt[ord(ch) - 48] += 1
            denom = 1
            for c in cnt:
                if c:
                    denom *= fact[c]
            total += fact[n - 1] * (n - cnt[0]) // denom
        return total

