import sys
from collections import defaultdict

def main():
    data = sys.stdin.read().split()
    N = int(data[0]); M = int(data[1]); S = data[2]
    MOD = 998244353

    # character classes by match-bitmask over positions of S
    masks = {}
    for i, ch in enumerate(S):
        masks[ch] = masks.get(ch, 0) | (1 << i)
    classes = [(m, 1) for m in masks.values()]
    other = 26 - len(masks)
    if other > 0:
        classes.append((0, other))

    def step(v, mask):
        nv = [0] * (N + 1)
        for i in range(1, N + 1):
            a = nv[i - 1]
            b = v[i]
            c = v[i - 1] + (1 if (mask >> (i - 1)) & 1 else 0)
            if a >= b:
                nv[i] = a if a >= c else c
            else:
                nv[i] = b if b >= c else c
        return tuple(nv)

    init = tuple([0] * (N + 1))
    dp = {init: 1}
    cache = {}

    for _ in range(M):
        ndp = defaultdict(int)
        for v, cnt in dp.items():
            for mask, w in classes:
                key = (v, mask)
                nv = cache.get(key)
                if nv is None:
                    nv = step(v, mask)
                    cache[key] = nv
                ndp[nv] = (ndp[nv] + cnt * w) % MOD
        dp = ndp

    ans = [0] * (N + 1)
    for v, cnt in dp.items():
        ans[v[N]] = (ans[v[N]] + cnt) % MOD
    sys.stdout.write(' '.join(map(str, ans)) + '\n')

