def main():
    data = sys.stdin.buffer.read().split()
    N = int(data[0]); M = int(data[1])
    A = [int(x) - 1 for x in data[2:2 + N]]
    MOD = 998244353

    try:
        import numpy as np
        has_np = True
    except Exception:
        has_np = False

    color = [0] * N
    on_cycle = [False] * N
    cycles = []
    for s in range(N):
        if color[s]:
            continue
        path = []
        pos = {}
        u = s
        while color[u] == 0:
            color[u] = 1
            pos[u] = len(path)
            path.append(u)
            u = A[u]
        if color[u] == 1:
            cyc = path[pos[u]:]
            cycles.append(cyc)
            for w in cyc:
                on_cycle[w] = True
        for w in path:
            color[w] = 2

    children = [[] for _ in range(N)]
    for i in range(N):
        if not on_cycle[i]:
            children[A[i]].append(i)

    order = []
    depth = [-1] * N
    dq = []
    for cyc in cycles:
        for c in cyc:
            depth[c] = 0
            dq.append(c)
    head = 0
    while head < len(dq):
        u = dq[head]; head += 1
        order.append(u)
        d = depth[u] + 1
        for w in children[u]:
            depth[w] = d
            dq.append(w)

    G = [None] * N
    ans = 1

    if has_np:
        import numpy as np
        base_arr = np.arange(1, M + 1, dtype=np.int64)
        for t in reversed(order):
            if depth[t] == 0:
                continue
            ch = children[t]
            if ch:
                arr = None
                for c in ch:
                    g = G[c]
                    arr = g.copy() if arr is None else (arr * g) % MOD
                G[t] = np.cumsum(arr) % MOD
                for c in ch:
                    G[c] = None
            else:
                G[t] = base_arr
        for cyc in cycles:
            arr = None
            for c in cyc:
                for t in children[c]:
                    g = G[t]
                    arr = g.copy() if arr is None else (arr * g) % MOD
            if arr is None:
                S = M % MOD
            else:
                S = int(arr.sum()) % MOD
            ans = ans * S % MOD
    else:
        base = list(range(1, M + 1))
        for t in reversed(order):
            if depth[t] == 0:
                continue
            ch = children[t]
            if ch:
                arr = None
                for c in ch:
                    g = G[c]
                    if arr is None:
                        arr = g[:]
                    else:
                        arr = [x * y % MOD for x, y in zip(arr, g)]
                G[t] = [x % MOD for x in accumulate(arr)]
                for c in ch:
                    G[c] = None
            else:
                G[t] = base
        for cyc in cycles:
            arr = None
            for c in cyc:
                for t in children[c]:
                    g = G[t]
                    if arr is None:
                        arr = g[:]
                    else:
                        arr = [x * y % MOD for x, y in zip(arr, g)]
            if arr is None:
                S = M % MOD
            else:
                S = sum(arr) % MOD
            ans = ans * S % MOD

    print(ans)

