    limit = int(round(N ** (1.0 / 3.0)))
    while limit ** 3 > N:
        limit -= 1
    while (limit + 1) ** 3 <= N:
        limit += 1
    for d in range(1, limit + 1):
        if N % d:
            continue
        m = N // d
        disc = 12 * m - 3 * d * d
        if disc <= 0:
