class Solution:
    def subarraySum(self, nums: List[int]) -> int:
        prefix = [0] + list(accumulate(nums))
        total = 0
        for i, v in enumerate(nums):
            start = max(0, i - v)
            total += prefix[i + 1] - prefix[start]
        return total

class Solution:
    def countPartitions(self, nums: List[int]) -> int:
        # left - right = (total - right) - right = total - 2*right
        # parity of the difference equals parity of the total sum,
        # so the difference is even for every partition iff total is even.
        return len(nums) - 1 if sum(nums) % 2 == 0 else 0

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        # offline_until[u]: time at which user u comes back online.
        # User u is online at time t iff t >= offline_until[u] (status change
        # processed before a message at the same timestamp).
        offline_until = [0] * numberOfUsers

        # Process events by timestamp; OFFLINE before MESSAGE on ties.
        evs = sorted(events, key=lambda e: (int(e[1]), 0 if e[0] == "OFFLINE" else 1))

        for typ, ts, payload in evs:
            t = int(ts)
            if typ == "OFFLINE":
                offline_until[int(payload)] = t + 60
            else:
                for tok in payload.split():
                    if tok == "ALL":
                        for u in range(numberOfUsers):
                            mentions[u] += 1
                    elif tok == "HERE":
                        for u in range(numberOfUsers):
                            if t >= offline_until[u]:
                                mentions[u] += 1
                    else:
                        mentions[int(tok[2:])] += 1

        return mentions

class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        n = len(nums)
        # prefix count of value k
        prek = [0] * (n + 1)
        for i, x in enumerate(nums):
            prek[i + 1] = prek[i] + (1 if x == k else 0)
        base = prek[n]  # frequency of k without any change

        # positions of every other value
        pos = {}
        for i, x in enumerate(nums):
            if x != k:
                if x in pos:
                    pos[x].append(i)
                else:
                    pos[x] = [i]

        best_gain = 0
        for P in pos.values():
            m = len(P)
            cur = 0
            for i in range(m):
                cur += 1  # picking one more occurrence of v into the window
                if cur > best_gain:
                    best_gain = cur
                if i + 1 < m:
                    # k's strictly between P[i] and P[i+1] are lost
                    cur -= prek[P[i + 1]] - prek[P[i] + 1]
                    if cur < 0:
                        cur = 0
        return base + best_gain

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        MAX = 100001
        best = [-1] * MAX
        seen = [False] * MAX
        for j, v in enumerate(elements):
            if seen[v]:
                continue
            seen[v] = True
            for m in range(v, MAX, v):
                if best[m] == -1:
                    best[m] = j
        return [best[g] for g in groups]

class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        ans = 0
        for good in ({'N', 'E'}, {'E', 'S'}, {'S', 'W'}, {'W', 'N'}):
            total = 0
            neg = 0
            for c in s:
                if c in good:
                    total += 1
                else:
                    total -= 1
                    neg += 1
                cur = total + 2 * min(k, neg)
                if cur > ans:
                    ans = cur
        return ans

class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        # A valid substring of length k must be exactly a maximal run
        # of one character whose length is exactly k (neighbors, if any,
        # are different by maximality of the run).
        n = len(s)
        i = 0
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            if j - i == k:
                return True
            i = j
        return False

class Solution:
    def hasSameDigits(self, s: str) -> bool:
        digits = [int(c) for c in s]
        while len(digits) > 2:
            digits = [(digits[i] + digits[i + 1]) % 10 for i in range(len(digits) - 1)]
