class Solution:
    def maxWeight(self, pizzas: List[int]) -> int:
        pizzas.sort(reverse=True)
        m = len(pizzas) // 4
        odd = (m + 1) // 2   # odd days gain the group max
        even = m // 2        # even days gain the group second max
        # Top `odd` pizzas are gained on odd days (each + 3 fillers).
        # Next 2*even pizzas paired adjacently: gain the smaller of each pair.
        return sum(pizzas[:odd]) + sum(pizzas[odd + 1: odd + 1 + 2 * even: 2])

class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        from collections import deque

        def solve(pop_cond):
            stack = deque()  # (val, cnt) groups of start positions; bottom = oldest
            cur = 0          # sum of min (or max) of subarrays ending at r, length <= k
            total = 0
            for r, v in enumerate(nums):
                # expire start position s = r - k (covered by bottom entry)
                if r >= k:
                    v0, c0 = stack.popleft()
                    cur -= v0
                    if c0 > 1:
                        stack.appendleft((v0, c0 - 1))
                # add nums[r]: merge dominated groups
                acc = 0
                while stack and pop_cond(stack[-1][0], v):
                    val, cnt = stack.pop()
                    cur -= val * cnt
                    acc += cnt
                stack.append((v, acc + 1))
                cur += v * (acc + 1)
                total += cur
            return total

        # min pass: pop while top >= v ; max pass: pop while top <= v
        return solve(lambda a, b: a >= b) + solve(lambda a, b: a <= b)

class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        groups = defaultdict(list)
        for i, v in enumerate(nums):
            groups[v].append(i)

        ans = [-1] * n
        for pos in groups.values():
            k = len(pos)
            if k == 1:
                continue
            for i in range(k):
                g_next = (pos[(i + 1) % k] - pos[i]) % n
                g_prev = (pos[i] - pos[(i - 1) % k]) % n
                ans[pos[i]] = min(g_next, n - g_next, g_prev, n - g_prev)

        return [ans[q] for q in queries]

