            S = 0
            for k in range(1, 18):
                lo = max(l, pow4[k - 1])
                hi = min(r, pow4[k] - 1)
                if lo <= hi:
                    S += k * (hi - lo + 1)
            total += (S + 1) // 2
        return total

class Solution:
