class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        delta = {}
        A = 0
        for _, y, l in squares:
            A += l * l
            delta[y] = delta.get(y, 0) + l
            t = y + l
            delta[t] = delta.get(t, 0) - l

        pts = sorted(delta)
        active = 0
        cur = 0  # exactly 2 * (area below current breakpoint), integer arithmetic

        for i in range(len(pts) - 1):
            b = pts[i]
            active += delta[b]
            if active:
                add = 2 * active * (pts[i + 1] - b)
                if cur + add >= A:
                    return b + (A - cur) / (2 * active)
                cur += add

        return float(pts[-1])  # unreachable safeguard (last segment always triggers)

