from bisect import bisect_left

class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        n = len(s)
        occ = {}
        for i, ch in enumerate(s):
            if ch in occ:
                occ[ch].append(i)
            else:
                occ[ch] = [i]
        letters = list(occ)

        # For each letter, compute its minimal "merged" interval:
        # expand [first,last] until every character occurring inside is fully contained.
        intervals = set()
        for c in letters:
            l, r = occ[c][0], occ[c][-1]
            changed = True
            while changed:
                changed = False
                for d in letters:
                    pos = occ[d]
                    idx = bisect_left(pos, l)
                    if idx < len(pos) and pos[idx] <= r:
                        # d occurs inside [l, r]
                        if pos[0] < l:
                            l = pos[0]
                            changed = True
                        if pos[-1] > r:
                            r = pos[-1]
                            changed = True
            # exclude the whole string (not a special substring)
            if l != 0 or r != n - 1:
                intervals.add((l, r))

        # Max number of pairwise disjoint intervals (activity selection greedy by end)
        cnt, last_end = 0, -1
        for st, en in sorted(intervals, key=lambda x: x[1]):
            if st > last_end:
                cnt += 1
                last_end = en

        return cnt >= k

