def main():
    data = sys.stdin.buffer.read().split()
    H = int(data[0]); W = int(data[1]); K = int(data[2])
    rows = [data[3 + i].decode() for i in range(H)]
    pad = K + 1
    W2 = W + 2 * pad
    F = 0
    for i in range(H):
        r = rows[i]
        b0 = i * W2 + pad
        for j in range(W):
            if r[j] == '.':
                F |= 1 << (b0 + j)
    H1 = H - 1
    W1 = W - 1
    # SH[key] for key = (dx+12)*25 + (dy+12): mask of start positions whose
    # (dx,dy)-translated cell is free (bit p set <=> F bit p + dx*W2+dy set)
    SH = [0] * 625
    for dx in range(-H1, H1 + 1):
        t0 = dx * W2
        kx = (dx + 12) * 25
        for dy in range(-W1, W1 + 1):
            t = t0 + dy
            SH[kx + dy + 12] = F >> t if t >= 0 else F << (-t)

    sys.setrecursionlimit(3000)

    def dfs(dx, dy, V, M, depth,
            SH=SH, KM1=K - 1, H1=H1, W1=W1,
            DIRS=((-1, 0), (1, 0), (0, -1), (0, 1))):
        total = 0
        if depth == KM1:
            for ex, ey in DIRS:
                nx = dx + ex; ny = dy + ey
                if -H1 <= nx <= H1 and -W1 <= ny <= W1:
                    key = (nx + 12) * 25 + ny + 12
                    if not V >> key & 1:
                        total += bin(M & SH[key]).count('1')
            return total
        for ex, ey in DIRS:
            nx = dx + ex; ny = dy + ey
            if -H1 <= nx <= H1 and -W1 <= ny <= W1:
                key = (nx + 12) * 25 + ny + 12
                b = 1 << key
                if not V & b:
                    M2 = M & SH[key]
                    if M2:
                        total += dfs(nx, ny, V | b, M2, depth + 1)
        return total

    print(dfs(0, 0, 1 << (12 * 25 + 12), F, 0))

