class Solution:
    def minTimeToReach(self, moveTime: List[List[int]]) -> int:
        n, m = len(moveTime), len(moveTime[0])
        INF = float('inf')
        dist = [[INF] * m for _ in range(n)]
        dist[0][0] = 0
        heap = [(0, 0, 0)]  # (arrival_time, i, j)

        while heap:
            t, i, j = heapq.heappop(heap)
            if t > dist[i][j]:
                continue  # stale entry
            if i == n - 1 and j == m - 1:
                return t
            for di, dj in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < m:
                    # Must start the move at max(current time, target's open time),
                    # then the move itself takes 1 second.
                    nt = max(t, moveTime[ni][nj]) + 1
                    if nt < dist[ni][nj]:
                        dist[ni][nj] = nt
                        heapq.heappush(heap, (nt, ni, nj))

        return dist[n - 1][m - 1]

class Solution:
    def hasIncreasingSubarrays(self, nums: List[int], k: int) -> bool:
        n = len(nums)
        # inc[i] = length of longest strictly increasing run starting at i
        inc = [1] * n
        for i in range(n - 2, -1, -1):
            if nums[i] < nums[i + 1]:
                inc[i] = inc[i + 1] + 1

        # Try every start a of the first subarray; second starts at a + k
        for a in range(n - 2 * k + 1):
            if inc[a] >= k and inc[a + k] >= k:
                return True
        return False

