class Solution:
    def subsequencePairCount(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)
        maxV = max(nums)

        # cnt[m] = number of elements divisible by m
        freq = [0] * (maxV + 1)
        for x in nums:
            freq[x] += 1
        cnt = [0] * (maxV + 1)
        for dv in range(1, maxV + 1):
            f = freq[dv]
            if f:
                for m in range(dv, maxV + 1, dv):
                    cnt[m] += f

        # Möbius function via linear sieve
        mu = [0] * (maxV + 1)
        mu[1] = 1
        is_comp = [False] * (maxV + 1)
        primes = []
        for i in range(2, maxV + 1):
            if not is_comp[i]:
                primes.append(i)
                mu[i] = -1
            for p in primes:
                ip = i * p
                if ip > maxV:
                    break
                is_comp[ip] = True
                if i % p == 0:
                    mu[ip] = 0
                    break
                mu[ip] = -mu[i]

        pw2 = [1] * (n + 1)
        pw3 = [1] * (n + 1)
        for k in range(1, n + 1):
            pw2[k] = pw2[k - 1] * 2 % MOD
            pw3[k] = pw3[k - 1] * 3 % MOD

        ans = 0
        for d in range(1, maxV + 1):
            lst = []
            for i in range(1, maxV // d + 1):
                if mu[i] and cnt[d * i]:
                    lst.append((d * i, mu[i]))
            for a, ma in lst:
                ca = cnt[a]
                for b, mb in lst:
                    cb = cnt[b]
                    l = a // gcd(a, b) * b
                    t = cnt[l] if l <= maxV else 0
                    m = (pw3[t] * pw2[ca - t] % MOD * pw2[cb - t]
                         - pw2[ca] - pw2[cb] + 1) % MOD
                    ans = (ans + ma * mb * m) % MOD
        return ans

