class Solution:
    def minArraySum(self, nums: List[int], k: int, op1: int, op2: int) -> int:
        INF = float('inf')
        # dp[a][b] = min sum so far having used a op1's and b op2's
        dp = [[INF] * (op2 + 1) for _ in range(op1 + 1)]
        dp[0][0] = 0

        for x in nums:
            ndp = [[INF] * (op2 + 1) for _ in range(op1 + 1)]
            for a in range(op1 + 1):
                for b in range(op2 + 1):
                    cur = dp[a][b]
                    if cur == INF:
                        continue
                    # do nothing
                    if cur + x < ndp[a][b]:
                        ndp[a][b] = cur + x
                    # op1 only: ceil(x/2)
                    if a < op1:
                        v = cur + (x + 1) // 2
                        if v < ndp[a + 1][b]:
                            ndp[a + 1][b] = v
                    # op2 only: x - k (needs x >= k)
                    if b < op2 and x >= k:
                        v = cur + x - k
                        if v < ndp[a][b + 1]:
                            ndp[a][b + 1] = v
                    # both operations (either order)
                    if a < op1 and b < op2:
                        h = (x + 1) // 2
                        # op1 then op2 (needs ceil(x/2) >= k)
                        if h >= k:
                            v = cur + h - k
                            if v < ndp[a + 1][b + 1]:
                                ndp[a + 1][b + 1] = v
                        # op2 then op1 (needs x >= k)
                        if x >= k:
                            v = cur + ((x - k + 1) // 2)
                            if v < ndp[a + 1][b + 1]:
                                ndp[a + 1][b + 1] = v
            dp = ndp

        return min(min(row) for row in dp)

