    def maxScore(self, n: int, k: int, stayScore: List[List[int]], travelScore: List[List[int]]) -> int:
        # dp[c] = max points earned so far, currently in city c
        dp = [0] * n  # starting city is free choice, so all 0 before day 0
        for i in range(k):
            ndp = [0] * n
            for c in range(n):
                # stay in city c
                best = dp[c] + stayScore[i][c]
                # move from some prev city p to c
                for p in range(n):
                    if p != c:
                        cand = dp[p] + travelScore[p][c]
                        if cand > best:
                            best = cand
                ndp[c] = best
            dp = ndp
        return max(dp)

