class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        pt_set = set((x, y) for x, y in points)
        n = len(points)
        best = -1
        for i in range(n):
            x1, y1 = points[i]
            for j in range(n):
                x2, y2 = points[j]
                # treat (x1,y1) as bottom-left, (x2,y2) as top-right (non-degenerate)
                if x1 < x2 and y1 < y2:
                    # other two corners must exist
                    if (x1, y2) in pt_set and (x2, y1) in pt_set:
                        corners = {(x1, y1), (x2, y2), (x1, y2), (x2, y1)}
                        valid = True
                        for k in range(n):
                            xk, yk = points[k]
                            if (xk, yk) in corners:
                                continue
                            # any other point inside or on border invalidates
                            if x1 <= xk <= x2 and y1 <= yk <= y2:
                                valid = False
                                break
                        if valid:
                            best = max(best, (x2 - x1) * (y2 - y1))
        return best

