class Solution:
    def findMinimumTime(self, strength: List[int], K: int) -> int:
        n = len(strength)
        full = (1 << n) - 1
        INF = float('inf')
        dp = [INF] * (1 << n)
        dp[0] = 0

        for mask in range(1 << n):
            if dp[mask] == INF:
                continue
            broken = bin(mask).count('1')
            x = 1 + broken * K
            base = dp[mask]
            for i in range(n):
                bit = 1 << i
                if mask & bit:
                    continue
                cost = (strength[i] + x - 1) // x
                nm = mask | bit
                if base + cost < dp[nm]:
                    dp[nm] = base + cost

        return dp[full]

