try:
    import numpy as np
except Exception:
    np = None


class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n, m = len(source), len(pattern)
        T = len(targetIndices)

        # cost[i] = 1 if index i is a removable (target) index
        cost = [0] * n
        for idx in targetIndices:
            cost[idx] = 1

        # dp[j] = minimum number of target indices used by an embedding of
        # pattern[:j] into the source prefix processed so far.
        # answer = T - dp[m]

        if np is not None:
            pat = np.frombuffer(pattern.encode(), dtype=np.uint8)
            BIG = 1 << 40
            dp = np.full(m + 1, BIG, dtype=np.int64)
            dp[0] = 0
            # per character: positions where pattern char != c (forbidden transitions)
            tab = {}
            for ch in set(source):
                if ch in pattern:
                    tab[ch] = ~(pat == ord(ch))
            for i in range(n):
                nmask = tab.get(source[i])
                if nmask is None:
                    continue
                cand = dp[:m] + cost[i]      # dp_old[j-1] + cost for dp_new[j]
                cand[nmask] = BIG            # forbid j where pattern[j-1] != source[i]
                np.minimum(dp[1:], cand, out=dp[1:])
            return T - int(dp[m])

        # Pure Python fallback: same DP, in-place, j processed in descending order
        INF = float('inf')
        ml = {}
        for j in range(m, 0, -1):
            ml.setdefault(pattern[j - 1], []).append(j)
        dp = [0] + [INF] * m
        for i in range(n):
            lst = ml.get(source[i])
            if not lst:
                continue
            if cost[i]:
                for j in lst:
                    v = dp[j - 1] + 1
                    if v < dp[j]:
                        dp[j] = v
            else:
                for j in lst:
                    v = dp[j - 1]
                    if v < dp[j]:
                        dp[j] = v
        return T - dp[m]

