    def calculateScore(self, s: str) -> int:
        stacks = [[] for _ in range(26)]
        total = 0
        for i, ch in enumerate(s):
            c = ord(ch) - 97
            m = 25 - c
            if stacks[m]:
                total += i - stacks[m].pop()
            else:
                stacks[c].append(i)
        return total

class Solution:
    def answerString(self, word: str, numFriends: int) -> str:
        if numFriends == 1:
            return word
        n = len(word)
        m = n - numFriends + 1  # max possible length of any piece
        return max(word[i:i + m] for i in range(n))

from typing import List

class Solution:
    def buttonWithLongestTime(self, events: List[List[int]]) -> int:
        best_idx = events[0][0]
        best_time = events[0][1]
        for i in range(1, len(events)):
            t = events[i][1] - events[i - 1][1]
            if t > best_time or (t == best_time and events[i][0] < best_idx):
                best_time = t
                best_idx = events[i][0]
        return best_idx

from typing import List

class Solution:
    def checkValidCuts(self, n: int, rectangles: List[List[int]]) -> bool:
        def count_clusters(intervals):
            intervals.sort()
            count = 0
            cur_end = -1
            for s, e in intervals:
                if s >= cur_end:
                    # No strict overlap with current cluster -> separable by a cut
                    count += 1
                    cur_end = e
                elif e > cur_end:
                    cur_end = e
            return count

        xs = [(r[0], r[2]) for r in rectangles]
        ys = [(r[1], r[3]) for r in rectangles]
        return count_clusters(xs) >= 3 or count_clusters(ys) >= 3

class Solution:
    def maxDistinctElements(self, nums: List[int], k: int) -> int:
        nums.sort()
        count = 0
        last = -(1 << 62)  # below any reachable value (x - k >= 1 - 1e9)
        for x in nums:
            v = max(x - k, last + 1)
            if v <= x + k:
                count += 1
                last = v
        return count

class Solution:
    def hasMatch(self, s: str, p: str) -> bool:
        pre, suf = p.split('*')
        n = len(s)
        lp = len(pre)
        for i in range(n - lp + 1):
            if s[i:i + lp] == pre and s.find(suf, i + lp) != -1:
                return True
        return False
